  t.age,                                                                        -- Stated: hasAge.
  t.attends,                                                                    -- Stated: the place this individual attends (attends). Its range is School.
  calc_individuals_attends_label(t.individual_id) AS attends_label,             -- Order 1. The name of the place attended.
